def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            minr = min(y for y,x in cells)
            minc = min(x for y,x in cells)
            shape = [(y-minr, x-minc) for y,x in cells]
            objs.append((minc, color, shape))
    objs.sort()
    out = [[0]*w for _ in range(h)]
    r0 = c0 = 0
    prevmaxr = prevmaxc = 0
    for i, (_, color, shape) in enumerate(objs):
        if i == 0:
            r0 = c0 = 0
        else:
            r0, c0 = prevmaxr, prevmaxc
        for dr, dc in shape:
            y, x = r0+dr, c0+dc
            if 0 <= y < h and 0 <= x < w and out[y][x] == 0:
                out[y][x] = color
        prevmaxr = r0 + max(y for y,x in shape)
        prevmaxc = c0 + max(x for y,x in shape)
    return out
